 {id:'ai',title:'Generative AI for educators',author:'Google',url:'https://grow.google/ai-for-educators/',rights:'Official learning resource; external reference',assigned:'Prompting, checking outputs, bias and responsible classroom use; use invented examples and protect learner information.'}
