export type PreparationDay={day:number;title:string;goal:string;explain:string;demonstrate:string;build:string[];game:{prompt:string;options:string[];correct:number;why:string};teachBack:string;output:string;reflect:string;reading:{id:string;section:string}[]};
export const dailyRhythm=[{label:'Recall and notice',minutes:15},{label:'Read and watch a short demonstration',minutes:30},{label:'Build and test',minutes:55},{label:'Play and debug',minutes:20},{label:'Teach it back',minutes:35},{label:'Reflect and collect evidence',minutes:15},{label:'Two short screen breaks',minutes:10}];
export const preparationCourses:Record<PreparationProgramme,{title:string;promise:string;outcome:string;days:PreparationDay[]}>= {
 elytech:{title:'ElyTech',promise:'Help a child discover that “I cannot do it yet” is a beginning, not an identity.',outcome:'Leave with a small teaching kit: a number activity, a keyboard practice plan, an original Scratch story, a Canva learning resource and a lesson you can explain with care.',days:[
 {day:1,title:'See the learner before the screen',goal:'Turn a demonstration into an opportunity for a learner to think and try.',explain:'Imagine you have explained the same thing three times, and a child is still quiet. Is the child unable to learn, or have we only offered one way to understand? Start with an action: sort objects, trace a route, move a finger. Ask what the learner notices before naming the idea. Chapter I of Piaget and Inhelder studies infancy; its useful question for us is how activity becomes understanding. Later sections on symbols and concrete reasoning connect more directly to school learning. These are lenses for planning, not fixed limits on a child.',demonstrate:'Lay out five bottle tops, rearrange them, then ask a partner how many there are and why. Listen before correcting. Repeat with a drawing and a number symbol; notice what support changes the explanation.',build:['Write one observable goal: the learner finds F and J independently, rather than “understands typing”.','Prepare an object, a picture and a short demonstration for that goal.','Practise with an adult partner or an imaginary class; record what you would watch for. Do not collect children’s data.'],game:{prompt:'A child copies your steps but cannot explain or repeat them alone. What do you try?',options:['Add a smaller independent attempt and ask what they noticed.','Repeat the whole lecture louder.','Label the child a weak learner.'],correct:0,why:'Copying is not the same as understanding. A small independent attempt gives you evidence for the next step.'},teachBack:'Give a five-minute keyboard introduction. Pause twice for the learner to act and once for them to explain.',output:'A one-page observation-to-action lesson plan.',reflect:'Which assumption about a learner did you replace with something you could observe?',reading:[{id:'child',section:'Chapter I overview; chapter III symbols/play and chapter IV concrete reasoning, selected passages.'}]},
 {day:2,title:'Your hands can hold a number',goal:'Represent 0–9 accurately using the right hand before introducing tens.',explain:'A number is not just something on the board. In Chisanbop, the right hand holds units: each of its four fingers is one and its thumb is five. The left hand holds tens: each of its four fingers is ten and its thumb is fifty. Clear both hands to show zero. Establish which hand is which before mirroring a class demonstration. A child may need a drawn hand, counters or extra movement practice; the aim is place value, not a performance of speed.',demonstrate:'Show 0, 3, 5, 7 and 9 slowly. Say that 7 is five and two. Lift all fingers to reset between numbers. Use the labelled hand values in this lesson to check which finger carries which value; practise gentle presses on a desk.',build:['Make your own labelled units-hand card.','Practise ten shuffled values from 0–9; check each by decomposing it into five and ones.','Create a three-minute “show it, say it, explain it” routine with an accessible counter alternative.'],game:{prompt:'The right thumb and two right fingers are pressed. What is represented?',options:['3','7','70'],correct:1,why:'The right thumb is five units; the two right fingers add two units.'},teachBack:'Teach a partner 5 and 7 without asking them to memorise every hand position at once.',output:'An original units-hand practice card and a short demonstration script.',reflect:'How will a learner with limited finger movement participate with equal dignity?',reading:[{id:'chisanbop',section:'Supplied PDF pages 1–4: finger names, values and representation.'}]},
 {day:3,title:'Make the tens visible',goal:'Explain units, tens and a first simple addition without hiding the regrouping.',explain:'If a market seller exchanges ten one-naira counters for one ten-naira counter, the amount has not changed. Chisanbop makes that exchange visible between hands. First read two-digit values; do not rush into arithmetic. For a first regrouping, build 9 and add 1: clear the nine units and represent one ten. Explain why the value is ten rather than teaching a movement to imitate. Advanced carries and subtraction need further coached practice beyond this induction.',demonstrate:'Show 12 as one left finger and two right fingers, then 17 using the right thumb as well. Work 2 + 3 without regrouping, then 9 + 1 with counters alongside the hands.',build:['Create ten original two-digit number cards, including 10, 15 and 50.','Check each representation against the on-page finger values and a counter model.','Prepare a worked example, a guided example and an independent example; record one common mistake and a kind correction.'],game:{prompt:'A learner uses the left thumb to represent five units. What needs revisiting?',options:['Left/right place value: that thumb represents fifty.','Nothing; all thumbs are five.','The child must practise faster.'],correct:0,why:'The hands have different place values. Rebuild the meaning before asking for speed.'},teachBack:'Explain 9 + 1 using hands, counters and a number sentence. Ask the learner to connect the three.',output:'A place-value mini-lesson with an answer key.',reflect:'Where might a correct-looking movement conceal a misunderstanding?',reading:[{id:'chisanbop',section:'PDF pages 4–6 and introductory addition examples; verify against diagrams.'},{id:'child',section:'Chapter IV: number and concrete operations, selected passage.'}]},
 {day:4,title:'Keyboard confidence before speed',goal:'Build a manageable home-key practice that values accuracy and comfort.',explain:'Think about learning a familiar route. At first you look for every landmark. With practice, you need fewer reminders. Typing develops in a similar way. F and J often have raised markers; home keys give the hands a place to return. Comfortable posture, short sets and correct movement matter more than a public speed ranking. Basic 1–2 learners focus on keyboard and Chisanbop; older primary learners also meet Scratch and Canva when supported.',demonstrate:'Find the F and J markers without looking, place fingers gently, then type “fj fj ff jj”. Pause, reset and check the screen. Add a small group of keys only when the learner is ready.',build:['Prepare a paper keyboard for a no-device demonstration.','Design three short accuracy rounds with rests and a self-check.','Write an adaptation for a smaller hand, unfamiliar letter recognition or motor-access need.'],game:{prompt:'A learner becomes more accurate but types fewer words today. What do you say?',options:['Your accuracy improved; let’s practise one small next step.','That is failure because only speed matters.','Use the fastest child’s result instead.'],correct:0,why:'Specific feedback helps the learner recognise progress and choose a next action.'},teachBack:'Explain home keys in two minutes, then let the partner practise without your hands doing the work.',output:'A 15-minute keyboard activity with three practice rounds.',reflect:'What will you measure besides words per minute?',reading:[{id:'child',section:'Chapter I action and adaptation; apply cautiously to practice design.'}]},
 {day:5,title:'Make room for every learner',goal:'Plan meaningful participation when devices and confidence are uneven.',explain:'One laptop between three learners can become three people watching, or three people thinking. Give each person a job: driver, navigator and checker. Rotate the jobs on a clear signal. A paper keyboard, an instruction card and a prediction task can keep learning moving when power or internet fails. Never imply that a learner without a device is less committed. For home practice, use an approved parent-device route without asking a child to publish private details.',demonstrate:'One partner describes three keyboard actions, one performs them and another checks the result. Change roles. Then repeat with paper to see which learning goal survives the device change.',build:['Draw a rotation plan for six learners and two laptops.','Create a no-power version of the same objective.','Prepare a take-home practice instruction a parent can understand without being a technology teacher.'],game:{prompt:'Only the driver is learning during a shared-device activity. What changes first?',options:['Give the navigator a prediction and the checker a test, then rotate.','Let the fastest learner drive for the whole lesson.','Cancel all participation for children without devices.'],correct:0,why:'A named role must involve thinking, not merely waiting for a turn.'},teachBack:'Run a five-minute shared-device simulation with fair role changes.',output:'A device-sharing and no-power practice plan.',reflect:'How will you know that the quiet learner contributed?',reading:[{id:'child',section:'Chapter IV interpersonal relations, selected passage.'},{id:'canva',section:'Teacher resource activities; use an offline paper equivalent where useful.'}]},
 {day:6,title:'A story that follows instructions',goal:'Use Scratch events and sequence to make an original short story.',explain:'A recipe for making pap has a starting point and an order. A program also needs a trigger and a sequence. In Scratch, a sprite is an object you can instruct; a backdrop sets the scene. Begin with one sprite and a green-flag event. Add a move and a speech block. Ask the learner to predict before running it. The supplied book explains these ideas using Scratch 2; follow the current interface instead of copying old screenshots.',demonstrate:'Make an original character say hello, move and ask for help fixing a school garden. Change the order of two blocks, predict the difference and test.',build:['Storyboard three moments on paper.','Build the first moment with one sprite and one starting event.','Add a second character and test that the story restarts predictably. Use original or permitted assets.'],game:{prompt:'The script runs only when you click its loose blocks. What could make it start from the green flag?',options:['Attach a “when green flag clicked” event.','Change only the backdrop colour.','Rename the project three times.'],correct:0,why:'The event provides the starting trigger; sequence controls what follows.'},teachBack:'Ask a partner to predict the effect of swapping two blocks, then let them test.',output:'An original three-scene Scratch story and a storyboard.',reflect:'Which question made your partner predict rather than copy?',reading:[{id:'scratch-book',section:'Opening concepts: scripts, events and sequencing.'},{id:'scratch',section:'Choose a beginner story/animation tutorial.'}]},
 {day:7,title:'Become a kind debugger',goal:'Explain repetition and use a predictable routine to investigate a bug.',explain:'A dance can repeat four steps without writing the same instruction four times. A loop repeats a group of actions. But a repeated mistake becomes a bigger mistake, so predict and test a small piece first. Debugging is not a judgement of intelligence. Say what you expected, describe what happened, change one thing and test again. This is a useful habit far beyond programming.',demonstrate:'Make a sprite trace a square with four forward-and-turn pairs, then replace the repeated pairs with a repeat block. Deliberately change the turn angle and ask a partner to investigate.',build:['Create a repeat-based pattern using your own colours.','Plant one deliberate, harmless bug and write a clue.','Revisit the Day 6 story and record one improvement based on testing.'],game:{prompt:'A sprite repeats the wrong movement. What is a useful first debugging step?',options:['Delete the entire project.','Compare the expected and actual result, then test one changed block.','Tell the learner coding is not for them.'],correct:1,why:'A small, testable change reveals more than random edits or blame.'},teachBack:'Coach a partner through your planted bug without taking over the mouse.',output:'A small Scratch pattern plus a before/after debugging note.',reflect:'What did you learn by allowing someone time to find the problem?',reading:[{id:'scratch-book',section:'Repetition and introductory debugging concepts.'},{id:'scratch',section:'A simple animation or game; use only the blocks needed.'}]},
 {day:8,title:'Canva: make the message clear',goal:'Build a simple learning card using hierarchy, alignment and contrast.',explain:'A beautiful poster that nobody can read has missed its work. Before opening Canva, choose one reader, one message and one action. A heading should be easier to notice than supporting text. Alignment makes the page feel organised; empty space gives ideas room. Contrast is about readability as well as colour. These ideas come before the tool, so a trainee can practise them on paper and still learn something useful.',demonstrate:'Sketch a “Return library books on Friday” card. Create an A4 design, add a heading and one supporting sentence, align them and export a PDF. Use only free elements and your own content.',build:['Draw two arrangements before selecting a template or blank page.','Build one card with two type sizes, a limited palette and enough space.','View it at phone size and in greyscale. Ask a partner what they notice first.'],game:{prompt:'The date is hidden in tiny text below six decorative pictures. What improves the message?',options:['Add more decoration.','Give the date a clear place in the hierarchy and remove distractions.','Make every word equally large.'],correct:1,why:'Hierarchy helps the reader find what matters, in the order it matters.'},teachBack:'Explain a design decision without saying “because it looks nice”.',output:'An original Canva learning card, exported with a short design rationale.',reflect:'Which element did you remove, and what became easier to understand?',reading:[{id:'design',section:'Chapter 3: visual elements, contrast and organisation.'},{id:'canva',section:'Beginner editor, text, alignment and export.'}]},
 {day:9,title:'Design something a child can use',goal:'Create a clear instruction sheet and test it with a reader.',explain:'Now make a resource that does work: a keyboard reminder, a counting card or a Scratch prediction sheet. Write one step per line and use pictures that clarify the action. Do not rely on colour alone; a learner should still follow numbered steps on a black-and-white printout. Choose images you have permission to use and avoid photographs or personal details of children. Check a current Canva export rather than assuming the template is accessible.',demonstrate:'Compare “Do the work” with “1. Find F and J. 2. Type fj four times. 3. Circle the pair you want to practise again.” Show how a learner can act on the second instruction.',build:['Choose one resource for Basic 1–2 or Basic 3–6 and state the intended learner.','Create three steps, one worked example and space for the learner’s response.','Test with an adult reader, note confusion and revise. Export a print-friendly copy.'],game:{prompt:'A worksheet says “click the red button”, but two buttons look similar in greyscale. What helps?',options:['Add a text label and position cue, then test again.','Use a brighter red only.','Remove every instruction.'],correct:0,why:'Labels and position make the instruction usable without colour alone.'},teachBack:'Let a partner use the sheet while you stay silent. Debrief what the page did not explain.',output:'A tested Canva teaching sheet and one revision note.',reflect:'Where did your design require you to stand beside the learner and explain?',reading:[{id:'design',section:'Chapter 2: define, test and improve a solution.'},{id:'canva',section:'Pages, sharing permissions and PDF export.'}]},
 {day:10,title:'From a story to a decision',goal:'Introduce a variable and a simple decision through a familiar game.',explain:'A score changes as a game continues. A variable is a named place for a value that may change; it is not a magical answer stored forever. A decision checks a condition and chooses what happens next. Use a small Scratch quiz rather than an elaborate game: ask, check, respond. Connect the written symbol, the spoken explanation and the visible action. Keep the number of new ideas small enough for a child to explain.',demonstrate:'Start a score at zero. Ask one question, add one for a correct response and show a helpful message for another response. Restart and confirm the score resets.',build:['Make a two-question quiz about an everyday topic without collecting a real name.','Add a score reset to the starting event.','Test one correct answer, one incorrect answer and a restart.'],game:{prompt:'A quiz starts with yesterday’s score. Which step is missing?',options:['Set the score to zero when the game starts.','Increase the font size only.','Remove the question.'],correct:0,why:'Initial state matters. A new run should begin from the intended value.'},teachBack:'Use a bowl and counters to explain a changing score before showing the variable.',output:'An original Scratch quiz and three test cases.',reflect:'Could the learner explain what the score means without reading your code?',reading:[{id:'scratch-book',section:'Variables and decisions: introductory concepts only.'},{id:'child',section:'Chapter III: symbolic function; selected section on representation.'}]},
 {day:11,title:'Use AI without giving up judgement',goal:'Use an AI draft as something to inspect, adapt and verify.',explain:'An assistant can suggest an explanation, but it cannot know this particular class as you do. Ask for a small, clear task and check the result. An LLM generates language from learned patterns; fluent writing is not evidence that a fact is true. Never enter a child’s name, results, photograph or private story into an unapproved tool. A good instructor can explain and correct a lesson without depending on AI to rescue it.',demonstrate:'Draft a fictional prompt for a five-minute keyboard exercise. Check whether it assumes each child owns a laptop, requires unsuitable accounts or teaches the wrong keys. Rewrite the weak parts.',build:['Write a prompt with audience, goal, available materials and constraints.','If an approved AI tool is available, compare its output with your plan; otherwise critique a deliberately flawed draft you write.','Keep a brief verification log: claim, check, change.'],game:{prompt:'An AI activity asks you to upload named children’s test results to personalise feedback. What next?',options:['Upload them because the answer sounds helpful.','Use invented examples and follow Forge’s approved privacy process.','Send the data to a second tool as well.'],correct:1,why:'Convenience does not remove the duty to protect learners’ information.'},teachBack:'Explain one AI limitation and one useful application in plain language.',output:'A reusable prompt, corrected lesson fragment and verification log.',reflect:'What decision did you make that the tool could not make for your class?',reading:[{id:'ai',section:'Responsible classroom use, prompting and checking outputs.'}]},
 {day:12,title:'Build a classroom people trust',goal:'Respond calmly to mistakes, online risks and learning differences.',explain:'A memorable lesson should be safe enough for someone to ask a question. Give feedback on the action, not the learner’s worth. Use school-approved accounts and appropriate sharing settings. If a learner sees upsetting content or reports harm, stop the activity, protect their privacy and follow the school and Forge safeguarding route. Do not investigate by asking a child to repeat or spread private material. Plan both support and a meaningful extension task.',demonstrate:'Rehearse a response to “I am stupid; mine never works.” Acknowledge the frustration, name one thing that worked and suggest one small next test.',build:['Write a calm classroom routine for starting, asking for help and ending a lesson.','Create a support version and an extension of the same Scratch or Canva goal.','Prepare a brief escalation checklist using placeholders for the school’s designated staff; do not invent contact details.'],game:{prompt:'A learner shares a private screenshot about another child. What should the instructor do?',options:['Show it to the whole class as an example.','Stop further sharing and follow the school’s safeguarding/reporting process.','Ask learners to repost it for discussion.'],correct:1,why:'Respond to the concern without expanding the harm or turning the class into investigators.'},teachBack:'Practise a respectful correction, a help request and a safe escalation with an adult partner.',output:'A classroom care checklist and two differentiated activities.',reflect:'Which words would help a learner try again without feeling exposed?',reading:[{id:'safety',section:'Safe browsing and responsible online behaviour.'},{id:'child',section:'Chapter IV interpersonal relations; selected passage.'}]},
 {day:13,title:'Teach a small lesson well',goal:'Rehearse a realistic lesson with evidence of learning.',explain:'You do not need to demonstrate everything you know to teach one thing well. Choose one skill, show a worked example, guide a short attempt and let the learner try independently. Prepare for a lost connection or a late start. Ask a question whose answer reveals thinking. During rehearsal, your partner is reviewing the explanation, not deciding your worth as a person.',demonstrate:'Use a simple lesson arc: “Here is what we are making; watch one example; try with me; now try a different one; tell me what changed.” Keep the goal visible.',build:['Choose Chisanbop, keyboard, Scratch or Canva for a 15-minute micro-lesson.','Prepare a low-device alternative and an independent check.','Rehearse, gather feedback on clarity and revise one specific step.'],game:{prompt:'Your lesson plan has twelve new skills in fifteen minutes. What is the best revision?',options:['Reduce it to one observable goal with practice and a check.','Speak twice as quickly.','Remove all learner practice.'],correct:0,why:'The learner needs time to attempt and understand, not simply watch a tour of features.'},teachBack:'Deliver your 15-minute rehearsal. Ask the reviewer to identify where a learner might get lost.',output:'A rehearsal plan, teaching resource and before/after revision.',reflect:'Which part will you change because of what the learner did, not because of what you planned?',reading:[{id:'canva',section:'Your selected resource only.'},{id:'scratch',section:'Your selected tutorial only.'}]},
 {day:14,title:'Take something useful with you',goal:'Assemble evidence, identify gaps honestly and plan the next month.',explain:'Perhaps you joined because you wanted a job. We hope you also leave these two weeks knowing that you can help someone understand something that once felt difficult. Collect what you made and explain what changed. A portfolio is stronger when it shows a revision and a lesson learned. Preparation completion does not promise employment; Forge’s practical review and school arrangements remain separate.',demonstrate:'Compare an early and revised instruction card. Explain the reader’s difficulty, the change you made and what evidence you would look for next.',build:['Collect your number activity, keyboard plan, Scratch project, Canva resource and lesson rehearsal.','Add an honest confidence map: ready to practise, needs coaching, not yet attempted.','Choose one skill for a 30-day continuation plan, with a small weekly goal.'],game:{prompt:'A trainee finishes all reading but cannot demonstrate a lesson independently. What should happen?',options:['Automatic school placement.','Further coached rehearsal and practical review.','Delete the trainee’s work.'],correct:1,why:'Reading is useful preparation; safe, clear teaching also needs practice and review.'},teachBack:'Give a ten-minute portfolio walkthrough showing one improvement and one question you still need help with.',output:'A personal starter portfolio and a 30-day growth plan.',reflect:'What can you now explain or build that you could not explain on Day 1?',reading:[{id:'child',section:'Return to your Day 1 notes; compare your teaching assumptions.'}]}
 ]},
 techup:{title:'TechUp',promise:'Help a young person look at a problem here and realise their ideas can become something useful.',outcome:'Leave with a small working prototype, a clear data story, a safety explanation and a teachable project. Sample every shared foundation, then practise a direction; two weeks is a starting point, not mastery of every field.',days:[
 {day:1,title:'Explain the web through a familiar place',goal:'Connect a visible web page to the different jobs behind it.',explain:'Think about a school noticeboard. The notices have a structure, a visual arrangement and sometimes an action you can take. HTML gives content meaning, CSS controls presentation and JavaScript can respond to an action. The internet connects devices; the web is one service using that connection. Do not use the two words as if they are identical. Begin with something a GSS learner recognises and let them map the parts.',demonstrate:'Sketch a notice, heading and “show details” button. Label the job of HTML, CSS and JavaScript. Explain that a real button can work with a keyboard as well as a mouse.',build:['Draw a school noticeboard and choose one useful interaction.','Write a three-sentence explanation of the page’s jobs.','Prepare an object or paper analogy, then explain where the analogy stops being accurate.'],game:{prompt:'Which part normally responds when a button reveals a notice?',options:['CSS alone','JavaScript responding to an event','The name of the image file'],correct:1,why:'HTML supplies the button, CSS styles it and JavaScript can handle the event and update content.'},teachBack:'Explain the three jobs without beginning with a list of definitions.',output:'A labelled page sketch and a short explanation a GSS learner can follow.',reflect:'What everyday example helped, and where could it mislead?',reading:[{id:'web',section:'Getting started: how the web works.'}]},
 {day:2,title:'Make a small page people can read',goal:'Build semantic HTML and readable CSS for an original notice.',explain:'A heading is more than large text; it tells readers and assistive technology what the next section concerns. Use paragraphs for text, links for navigation and buttons for actions. CSS can organise these elements without changing what they mean. A page that works on a narrow phone screen is more useful than one that looks good only on your laptop. Start small enough that you can explain every line.',demonstrate:'Create a heading, short paragraph and link for a fictional community reading event. Add a maximum text width, comfortable spacing and visible focus styles. Resize the browser.',build:['Create an index.html and a separate styles.css.','Use your own event copy, meaningful link text and sufficient contrast.','Test narrow width, keyboard navigation and zoom; record and fix one issue.'],game:{prompt:'A link says only “click here”. What improves it?',options:['Describe the destination, such as “Read the event programme”.','Make it blink.','Remove keyboard focus.'],correct:0,why:'Meaningful link text helps people decide where the link goes, including when links are read out of context.'},teachBack:'Show a partner how to change one heading and one style, then ask them to explain the difference.',output:'A simple HTML/CSS page and three usability checks.',reflect:'What did you change after testing at phone width?',reading:[{id:'web',section:'Semantic HTML; CSS fundamentals and text styling.'}]},
 {day:3,title:'Make a decision in code',goal:'Trace input, a condition and output in JavaScript and Python.',explain:'A bus fare rule can be described before it is coded: if the remaining balance covers the fare, allow the trip; otherwise show what is missing. A variable stores a value, a condition asks a true-or-false question and a loop repeats a step. JavaScript and Python have different syntax, but both can express those ideas. Teach a learner to predict the result and test boundaries before adding more features.',demonstrate:'Use invented values for balance and fare. Trace the case below the fare, exactly equal and above. Write pseudocode, then a tiny JavaScript or Python version; compare the other language without demanding mastery of both.',build:['Write a balance-check rule in everyday language.','Implement it in one language and label the equivalent parts in the other.','Test below, equal and above the threshold. Record expected and actual outputs.'],game:{prompt:'Your rule is balance > fare. A balance exactly equal to the fare is rejected. What boundary should you revisit?',options:['Whether the comparison should include equality.','The file’s font size.','The colour of the laptop.'],correct:0,why:'Boundary tests reveal whether the condition matches the actual rule.'},teachBack:'Act out input, decision and output with cards before showing code.',output:'A tiny decision program and a three-case test table.',reflect:'Can you explain why each test result occurs without asking AI?',reading:[{id:'web',section:'JavaScript variables, comparisons and events.'},{id:'python',section:'Variables and conditionals; selected introductory examples.'}]},
 {day:4,title:'Design before decorating',goal:'Use Canva and Figma for different design tasks.',explain:'A poster helps someone understand a message. A prototype helps us test how someone might complete a task. Canva is useful for a clear communication piece; Figma can help arrange screens and connect a prototype. Neither tool decides whether the idea is useful. Begin with a paper sketch and a single reader or user. Use text labels, consistent spacing and a clear next action.',demonstrate:'Sketch a request-for-library-book flow with a starting screen, a choice and confirmation. Contrast it with a single Canva event poster. Explain that a prototype is not a secure working application.',build:['Create a simple Canva communication card with original copy.','Make two linked Figma frames or a paper clickable-flow substitute.','Ask a partner to complete the task without your hints and revise one confusing point.'],game:{prompt:'A Figma prototype looks finished. Does it prove that accounts and data storage work?',options:['Yes, the colours prove it.','No; it tests an interaction idea, not the backend.','Only if it has a logo.'],correct:1,why:'A prototype can simulate a journey without implementing authentication, persistence or permissions.'},teachBack:'Explain one visual decision and one interaction decision separately.',output:'A message card and a two-screen prototype.',reflect:'What did a user try that you had not expected?',reading:[{id:'design',section:'Chapter 2 design process; chapter 3 organisation.'},{id:'canva',section:'Editor and export basics.'},{id:'figma',section:'UI/UX and prototypes.'}]},
 {day:5,title:'Find a problem worth solving',goal:'Turn an assumption into a small product hypothesis.',explain:'“We need an app” is a proposed solution. “Students lose track of borrowed books” is a problem we can investigate. Product design asks who has the problem, what happens now and what change would help. Speak to an adult practice partner or use a clearly fictional case. Do not collect children’s personal details or promise the school a product. A useful first test may be paper, not software.',demonstrate:'Compare “Would you love my app?” with “Tell me what happens when a book is not returned.” Identify which question reveals an existing experience rather than inviting praise.',build:['Write a problem statement for a fictional school library or community service.','Prepare three non-leading questions and role-play the interview.','Choose the smallest feature to test and define a useful success observation.'],game:{prompt:'Which question is least leading?',options:['Our brilliant app would help you, right?','What did you do the last time you could not find a book?','Would you give our app five stars?'],correct:1,why:'An account of a real or role-played task reveals behaviour more clearly than praise for a proposed solution.'},teachBack:'Explain why the problem matters without pitching ten features.',output:'A one-page product brief and a paper test.',reflect:'Which assumption would you test before writing more code?',reading:[{id:'figma',section:'Product design and user-centred design basics.'},{id:'design',section:'Chapter 2: define and research.'}]},
 {day:6,title:'Ask better questions of data',goal:'Organise clean records and explain what a spreadsheet can and cannot show.',explain:'A pile of exercise books is hard to count reliably when the same book appears twice. Data has similar problems. Use one row per record, one field per column and consistent values. An Excel table helps organise records, but it does not automatically enforce the relationships and permissions of a database system. Use invented library records, not student names or real results. Ask a specific question before choosing a formula.',demonstrate:'Enter fictional book category and copies borrowed. Find a duplicate, a blank and a number stored as text. Use SUM or COUNT appropriately, then check the result by hand on a small subset.',build:['Create twelve invented records with clear headings and units.','Clean three deliberate data-quality problems.','Use one formula and one table filter to answer two stated questions.'],game:{prompt:'The same loan appears twice. What should happen before presenting totals?',options:['Choose a prettier chart.','Check the duplicate and the meaning of each record.','Ignore it because Excel calculated a number.'],correct:1,why:'A correct formula over unreliable records can still produce a misleading answer.'},teachBack:'Explain a row, column and duplicate using physical cards before opening Excel.',output:'A clean fictional workbook and a data-quality checklist.',reflect:'What evidence supports your total, and what does it fail to measure?',reading:[{id:'excel',section:'1.2–1.3, 2.1–2.2 and 5.1.'},{id:'systems',section:'Chapter 4: data management, selected section.'}]},
 {day:7,title:'Tell the truth with a chart',goal:'Turn a small dataset into one honest, understandable insight.',explain:'A chart should help someone decide or ask a better question. State what was counted, over what period and in which units. Do not let a dramatic colour or an exaggerated scale do the arguing. Power BI connects, shapes and presents data; an attractive report is still only as reliable as its source and definitions. If installation is unavailable, explain the same insight with an Excel chart and a paper report sketch.',demonstrate:'Use your invented book loans to compare categories. Choose a bar chart, show labels and state one limitation. Compare that with a chart whose labels or baseline distort the impression.',build:['Import your fictional workbook into Power BI if available.','Create one readable visual and a plain-language title.','Write one supported observation, one limitation and one next question. Do not publish private data to a public workspace.'],game:{prompt:'A report has a striking total but no date range. What is missing?',options:['Context needed to interpret the number.','More animation only.','A second logo.'],correct:0,why:'Readers need definitions, units and time context before a total can support an interpretation.'},teachBack:'Explain the chart to a partner who has not seen the dataset.',output:'A one-page data story with its source and limitation.',reflect:'What would be an unfair claim to make from these records?',reading:[{id:'powerbi',section:'Introduction: building blocks and a first report.'},{id:'excel',section:'4.1: choosing a chart type.'}]},
 {day:8,title:'Follow a message through a network',goal:'Distinguish local networks, internet access and cloud services.',explain:'A message may travel from a laptop through Wi-Fi to a router, through an internet provider and on to a remote service. Wi-Fi is the local connection; a strong Wi-Fi signal does not prove the internet is working. A cloud service runs on someone else’s computing infrastructure with responsibilities shared between provider and user. SaaS is a ready-to-use service, PaaS a managed environment for building and IaaS rented infrastructure. These are useful distinctions, not things to memorise without an example.',demonstrate:'Draw a school dashboard request as a route. Use envelopes as data packets and a labelled address card to explain why destinations matter. Explain that the envelope analogy leaves out much real network behaviour.',build:['Draw a laptop-to-dashboard network map with Wi-Fi, router, ISP and service.','Compare an offline file with a synchronised cloud copy.','Create a safe troubleshooting order: device connection, local network, internet, then service status. Do not change a school router.'],game:{prompt:'Wi-Fi is connected but no internet site opens on any school device. What does that tell you?',options:['Wi-Fi and internet are identical.','The local wireless link alone does not prove upstream internet access.','All passwords must be shared publicly.'],correct:1,why:'Connectivity has layers. A working local link can coexist with an upstream outage.'},teachBack:'Explain one cloud service and what the user must still protect, such as account access and sharing.',output:'A labelled network map and a calm troubleshooting checklist.',reflect:'Which issue can you check safely, and when must you escalate?',reading:[{id:'systems',section:'Chapters 2–3: networks and cloud/service alternatives.'},{id:'network-book',section:'Opening LAN and internetworking overview; optional reference.'},{id:'cloud',section:'Section 2: service models; use familiar examples.'}]},
 {day:9,title:'Technology needs trust',goal:'Teach defensive security and find the right Nigerian legal references.',explain:'A borrowed key does not give permission to enter every room. Knowing how a system works does not give permission to access another person’s account. Teach passphrases, MFA, careful sharing, updates and phishing recognition using invented examples. Nigeria’s Cybercrimes Act 2015 must be read with the 2024 amendment; the amendment is not the whole Act. Distinguish practical safety advice from a legal claim, and check the current official text before naming an offence, deadline or penalty.',demonstrate:'Compare two fictional login messages. Check the actual domain and use a known, independent contact route instead of the message’s urgent link. Never collect or test real passwords in class.',build:['Create three fictional safety scenarios: suspicious login, accidental sharing and a lost device.','Write prevention and school-approved escalation steps for each.','Locate the 2015 Act and 2024 amendment, record their titles and explain why both are needed. No scanning or intrusion on live systems.'],game:{prompt:'A learner finds someone else’s password and wants to “test” their account. What is the safe response?',options:['Try it to see whether it works.','Do not access it; report privately through the approved school route.','Share it as a classroom puzzle.'],correct:1,why:'Capability is not permission. Defensive teaching protects accounts and limits further exposure.'},teachBack:'Explain phishing to a nontechnical adult without blaming people who are deceived.',output:'A classroom safety card and a checked legal-reference note.',reflect:'Which claim would you verify before presenting it as Nigerian law?',reading:[{id:'law-combined',section:'Official NCC-hosted PDF: 2015 Act with Amendment Act 2024; selected teacher-guided reference.'},{id:'law2015',section:'Original Act: teacher-guided orientation, not penalty memorisation.'},{id:'law2024',section:'Read amendments alongside the original.'},{id:'safety',section:'Safe browsing and responsible reporting.'}]},
 {day:10,title:'Write for somebody, not everybody',goal:'Plan clear content and a small, honest digital communication test.',explain:'A trader explaining a product to a neighbour chooses different words from a technical manual. Content writing starts with who needs the message, what they need to understand and what they can do next. Planning chooses the sequence and channel; digital marketing tests whether the message reaches the intended people and supports the intended outcome. A large view count alone does not prove understanding, enquiries or trust. Never invent testimonials, results or urgency.',demonstrate:'Write two versions of a fictional library event notice: one for students and one for parents. Keep the facts the same while changing the explanation and next action.',build:['Define one audience and one useful action.','Write a short notice, a headline and a three-post plan using only invented event details.','Choose one meaningful measure and one potential source of misleading results. Do not run paid ads.'],game:{prompt:'A campaign gets many views but no relevant enquiries. What should you examine?',options:['Audience, message, next action and measurement.','Only the size of the logo.','Whether you can invent a better result.'],correct:0,why:'Reach is one signal; it does not automatically demonstrate a useful outcome.'},teachBack:'Explain the same idea to a trader and a GSS learner without changing the facts.',output:'An audience brief, original copy and a simple content calendar.',reflect:'Which sentence serves the reader, and which sentence is only trying to impress?',reading:[{id:'marketing',section:'Audience needs, research and digital channels; optional short reading.'},{id:'canva',section:'Create a simple original communication visual.'}]},
 {day:11,title:'Build with AI, think for yourself',goal:'Use AI support while checking evidence, privacy and limitations.',explain:'AI is a broad field; machine learning is one approach within it. An LLM is a language model trained to generate and process language, not a guarantee of truth. Give a task, context and constraints, then inspect the answer. For teaching, the important question is whether you can verify and explain the output. Keep real school records, personal information and private code out of unapproved tools. Avoid making decisions about a child’s ability from an AI label.',demonstrate:'Ask for or write a draft explanation that incorrectly calls Wi-Fi “the internet”. Find the claim, check it against a reliable reference and rewrite it. Compare a vague prompt with a constrained one.',build:['Draft a prompt for a GSS explanation with a local example and a no-private-data constraint.','Check three claims against trusted references.','Use AI, if an approved tool is available, to suggest tests for your tiny program; run and inspect them yourself.'],game:{prompt:'An AI answer is confident and detailed. What establishes its accuracy?',options:['Its confidence alone.','Checking the claims and testing the relevant example.','The number of paragraphs.'],correct:1,why:'Fluent wording is not verification. Evidence and tests matter.'},teachBack:'Explain AI, machine learning and LLM with a clear boundary between the terms.',output:'A prompt, a claim-check table and a corrected explanation.',reflect:'Where did your judgement change the final result?',reading:[{id:'ai',section:'Prompting, responsible use and output checking.'},{id:'web',section:'Verify any generated web-code example against current documentation.'}]},
 {day:12,title:'Turn a good intention into a small project',goal:'Define scope, responsibility, sequence and a reviewable outcome.',explain:'A community clean-up needs more than enthusiasm: someone needs bags, someone knows the route and someone checks whether the work is finished. Project management makes those dependencies visible. State the problem, the smallest useful outcome, who does each task, what it depends on and how you will review it. A task board can help. Scrum is a complete framework, not another word for any board with three columns; learn a few useful ideas without pretending that a classroom simulation implements it all.',demonstrate:'Plan a fictional school library prototype. Separate “make a home page” from “confirm what information a borrower needs”. Show a dependency, a risk and a simple definition of done.',build:['Write a one-page project brief with scope and explicit exclusions.','Create six tasks with an owner, dependency and evidence of completion.','Hold a ten-minute review of the prototype and revise the next two tasks.'],game:{prompt:'A task says “make it good” and is marked done. What would help review it?',options:['A checkable outcome such as a tested screen and a working keyboard action.','A longer task name only.','Removing the reviewer.'],correct:0,why:'A clear definition of done makes progress inspectable and feedback specific.'},teachBack:'Explain a dependency using cooking or preparing a school event.',output:'A brief, a task board and a risk/next-step note.',reflect:'Which task was actually too large or too vague?',reading:[{id:'systems',section:'Chapters 12–13: project planning and agile ideas, short sections.'},{id:'scrum',section:'Goals, backlog and review; recognise the complete framework.'}]},
 {day:13,title:'Choose a direction, keep the foundations',goal:'Combine a chosen strength with two neighbouring skills.',explain:'A useful product needs more than a person who can code. A Builder makes a dependable interaction; a Storyteller makes its purpose understandable; a Strategist connects evidence, people and a plan. These are directions to explore, not boxes that define a young person forever. For secondary learners, GSS foundations make later choices informed. Your teaching should show the connection between fields rather than present each as an isolated definition.',demonstrate:'Use one library idea to show three artefacts: a tiny working page, a clear story explaining it and a task/data brief. Show how a change in user needs affects all three.',build:['Choose Builder, Storyteller or Strategist as your rehearsal focus.','Create a small artefact in that direction and evidence from two other foundations, such as a chart and a safety check.','Design a 15-minute GSS micro-lesson with a no-internet alternative and an independent check.'],game:{prompt:'A strong coder refuses to think about the user or explain the result. What growth is needed?',options:['Only more syntax memorisation.','Practice linking technical work to user needs, communication and evidence.','A promise never to collaborate.'],correct:1,why:'Working across related skills helps turn a technical exercise into something useful.'},teachBack:'Rehearse the micro-lesson; ask a partner to identify one moment of confusion.',output:'A direction-focused artefact and a reviewed teaching plan.',reflect:'Which neighbouring skill made your main work better?',reading:[{id:'web',section:'Builder: one current example.'},{id:'design',section:'Storyteller: hierarchy and audience.'},{id:'systems',section:'Strategist: evidence and project planning.'}]},
 {day:14,title:'Show what you can forge',goal:'Present a small honest portfolio and a plan for continued learning.',explain:'You do not have to know every field to begin learning with purpose. You do need to know what you can demonstrate, what needs coaching and what should be escalated. Bring the prototype, data story, safety explanation and teaching plan together. Show one failure that improved the work. Whatever happens with recruitment, these are tools you can use to keep building. Forge’s teaching placement and employment decisions require practical review; a reading checklist cannot make that decision.',demonstrate:'Present a two-minute before-and-after: the original assumption, the test, the change and what still does not work. Separate a real working feature from a mock-up.',build:['Assemble your page/prototype, clean dataset/chart, project plan and safety note.','Write an honest skills map and a 30-day continuation plan.','Rehearse a ten-minute demonstration and answer a question without AI assistance.'],game:{prompt:'Your prototype has a simulated login button. How should you describe it?',options:['A fully secure deployed account system.','A tested interaction mock-up; authentication is not implemented.','An enterprise system because it has a dashboard image.'],correct:1,why:'A clear boundary between demonstrated and simulated work builds trust.'},teachBack:'Explain the problem, your evidence and one limitation to a nontechnical reviewer.',output:'A starter portfolio, self-review and 30-day learning plan.',reflect:'What could you now help a secondary-school learner build responsibly?',reading:[{id:'scrum',section:'Review and improvement: apply the idea to your own learning.'}]}
 ]}
};
export function preparationJournal(programme:PreparationProgramme,day:number,notes=''){
 const course=preparationCourses[programme],lesson=course.days.find(item=>item.day===day);if(!lesson)throw Error('Unknown preparation day');
 return `${course.title} preparation · Day ${day}: ${lesson.title}\n\nGoal\n${lesson.goal}\n\nBuild\n${lesson.build.map((step,index)=>`${index+1}. ${step}`).join('\n')}\n\nTeach-back\n${lesson.teachBack}\n\nPortfolio evidence\n${lesson.output}\n\nReflection\n${lesson.reflect}\n\nMy practice notes\n${notes}\n\nThis is a personal practice journal, not a staff-reviewed assignment or proof of completion. Do not include real learner information.\n`;
}
